window.LD=window.LD||{};window.LD["replays"]={"rows":[{"t":"Chess: Mark v Ankit","at":"camp in Thornmere Ruins","h":["h18","h14"],"x":"Ankit takes the queen on move 9 and checks twice that it was really allowed. Mark confirms it, gloomily. Mark studies the board for a long minute on move 26, finds a queen missing and no way to win…","tag":"chess","k":"night","id":"n18","d":21,"s":1,"sd":21,"imp":3,"score":30},{"t":"Tench, 20 cm","at":"Wetfoot Ford","h":["h12","h14","h18","h3"],"x":"A first for the whole league: Matt McF pulls a tench at Wetfoot Ford and holds it up as proof.","k":"catch","id":"c22","d":21,"s":1,"sd":21,"imp":2,"score":20},{"t":"The Royal Vigil vs 2 Dire Wolves","r":"won","at":"The Wolf Den","h":["h10","h16"],"tag":"camp","k":"fight","id":"f56","d":21,"s":1,"sd":21,"imp":2,"score":20,"x":"The Royal Vigil wakes to 2 Dire Wolves in camp outside the Wolf Den in the middle of the night, and sees them off. Yomna landed Drain Life on the dire wolf hard enough to hear from the back. Mikolaj…"},{"t":"Cards for The Azure Stallions, read by Matt McF","at":"camp in Thornmere Ruins","h":["h12","h3"],"x":"On the last night before Thornmere Ruins, Matt McF spreads a cloak by the fire and reads the Pressed-Leaf Tarot for the whole of The Azure Stallions: the Four of Wands upside down, the Two of Cups…","k":"reading","id":"r89","d":21,"s":1,"sd":21,"imp":2,"score":20},{"t":"Met Ines","at":"the road between Frosthold and Veldrock","h":["h15"],"x":"Ryan stops to help Ines for the first time, who has rolled up her only copy of a map inside the wrong cloak.","k":"road","id":"r81","d":21,"s":1,"sd":21,"imp":2,"score":20},{"t":"The one that got away","at":"by a stream outside The Wolf Den","h":["h16","h10"],"x":"Mikolaj nearly lands a brown trout by a stream outside the Wolf Den, and then does not. The gap between those two things is a lifetime.","k":"catch","id":"c23","d":21,"s":1,"sd":21,"imp":1,"score":10},{"t":"The one that got away","at":"by a stream on the road to Veldrock","h":["h2"],"x":"Kev feels a mighty tug by a stream on the road to Veldrock and loses the fight. He thinks it was a silver roach.","k":"catch","id":"c24","d":21,"s":1,"sd":21,"imp":1,"score":10},{"t":"Ration-Bag Hash","at":"the Collapsed Mine","h":["h5","h13","h9","h7"],"x":"Griffin gets some Ration-Bag Hash on the go in the Collapsed Mine before anyone has their boots off. It holds together out of sheer spite.","tag":"camp","k":"meal","id":"m60","d":21,"s":1,"sd":21,"imp":1,"score":10},{"t":"Brown Trout in Brown Butter","at":"Cragtooth Warren","h":["h1","h8"],"x":"Brown Trout in Brown Butter in Cragtooth Warren: Spencer says it's the best thing Sam has ever made, and says so again in the morning. It has skin that crackles under the fork. The fish was Sam's 21…","tag":"camp","k":"meal","id":"m61","d":21,"s":1,"sd":21,"imp":1,"score":10},{"t":"Cards for Robert, read by Widow Cinder","at":"a cottage by the pithead","h":["h7"],"x":"Robert sits down across from Widow Cinder at a cottage by the pithead. Three cards: the Nine of Pentacles, the Page of Cups and the Hierophant. Even the candle seems to approve.","k":"reading","id":"r83","d":21,"s":1,"sd":21,"imp":1,"score":10},{"t":"On the road","at":"the road between Frosthold and Veldrock","h":["h15"],"x":"Ryan leaves a fresh pie on a gatepost beside the road to Veldrock where it is. Somebody must have left it for somebody, and that somebody is not Ryan.","k":"road","id":"r82","d":21,"s":1,"sd":21,"imp":1,"score":10},{"t":"the Pickaxe Rest","at":"the road between The Collapsed Mine and Veldrock","h":["h13","h5","h7","h9"],"x":"Robert finds Old Dunmar Kell at the Pickaxe Rest telling the ore-cart wheel a long story, and the wheel taking it well.","k":"road","id":"r84","d":21,"s":1,"sd":21,"imp":1,"score":10},{"t":"Gant's toll bridge","at":"the road between Ironhaven and Veldrock","h":["h2"],"x":"A row of anglers leans over the rail of Gant's toll bridge with their lines hanging in the current. Kev takes the end spot and is told it is the unlucky one.","k":"road","id":"r85","d":21,"s":1,"sd":21,"imp":1,"score":10},{"t":"Wetfoot Ford","at":"the road between Bleakmarsh and Thornmere Ruins","h":["h12","h14","h18","h3"],"x":"Matt McF tries the stepping stones at Wetfoot Ford and finds the third is a turtle. The turtle is kind about it.","k":"road","id":"r86","d":21,"s":1,"sd":21,"imp":1,"score":10},{"t":"Wetfoot Ford","at":"the road between Bleakmarsh and Thornmere Ruins","h":["h12","h14","h18","h3"],"x":"At Wetfoot Ford the fish are slow and the water is clear, and Matt McF comes up with a catch and a very wet sleeve.","k":"road","id":"r87","d":21,"s":1,"sd":21,"imp":1,"score":10},{"t":"Gant's toll bridge","at":"the road between Ironhaven and Veldrock","h":["h17","h4"],"x":"Garrett wades across under the toll bridge. Gant watches from above, eating an apple.","k":"road","id":"r88","d":21,"s":1,"sd":21,"imp":1,"score":10},{"t":"Met Captain Dorrit Salt","at":"the road between Cragtooth Warren and Ironhaven","h":["h2"],"x":"The Captain asks Kev to take the wheel of her cart for a spell. Kev steers it into a hedge, and is told that is the best landing she has seen.","k":"road","id":"r76","d":20,"s":1,"sd":20,"imp":3,"score":30},{"t":"Met Lark","at":"the road between Ironhaven and Veldrock","h":["h13","h5","h7","h9"],"x":"Lark asks Griffin to point to the quickest road. Griffin does, and Lark is already a speck on it.","k":"road","id":"r78","d":20,"s":1,"sd":20,"imp":3,"score":30},{"t":"Forge-Bellows Pepper Pot","h":["h2"],"x":"Forge-Bellows Pepper Pot is chalked up as the dish of the week at The Gilded Flagon, and Kev is first to try it. It has a ladle that has never been to the bottom. (2 silver 2 copper)","tag":"tavern","k":"meal","id":"m58","d":20,"s":1,"sd":20,"imp":2,"score":20},{"t":"The Verdant Sigil vs a Skeleton Archer, Risen Dead and a Skeleton","r":"won","at":"The Ashveil Crypts","h":["h6","h11","h19"],"tag":"dungeon","k":"fight","id":"f55","d":20,"s":1,"sd":20,"imp":1,"score":10,"x":"With Natasha hitting hardest, the Verdant Sigil dispatches a Skeleton Archer, Risen Dead and a Skeleton in the funeral feast hall on the second floor of the Ashveil Crypts. Everything after…"},{"t":"Spice-Barge Pilaf","h":["h2"],"x":"Kev finds the Carrbridge cart at the Ironhaven market and tries some Spice-Barge Pilaf, a long way from home. It has a raisin in every third mouthful, by tradition. (2 silver)","tag":"tavern","k":"meal","id":"m56","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"Varro Brothers' Spiced Bun","h":["h2"],"x":"Varro Brothers' Spiced Bun, eaten on an Ironhaven doorstep by Kev, who refuses to share. It is still warm and smells of cinnamon and grudge. (6 copper)","tag":"tavern","k":"meal","id":"m57","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"Frost-Elk Stew","h":["h17"],"x":"A cart from Frosthold has come for market day in Ironhaven, selling some Frost-Elk Stew. Chloe buys one to see what the fuss is. It has juniper in it that tastes of the pine woods. (1 silver 8 copper)","tag":"tavern","k":"meal","id":"m59","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"\"The Miner's Daughter\" by the fire","at":"camp in The Ashveil Crypts","h":["h11"],"x":"Natasha starts \"The Miner's Daughter\", stops, starts again, and decides it was the wrong song.","tag":"song","k":"night","id":"n15","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"Chess: Ankit v Mark","at":"camp in Bleakmarsh","h":["h14","h18"],"x":"Ankit brings the queen round to g7, and that is checkmate on move 22. I misjudged the bishop, Mark says, which is a rematch in nine words. Tomorrow Mark bears two packs and the full weight of a bad…","tag":"chess","k":"night","id":"n16","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"\"The Necromancer's Wedding\" by the fire","at":"camp in Cragtooth Warren","h":["h8","h1"],"x":"Spencer leads \"The Necromancer's Wedding\" with more courage than pitch, and Sam loves it for that. Maple yawns, loudly, in the second verse.","tag":"song","k":"night","id":"n17","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"Cards for Ryan, read by Grandmother Skaldi","at":"a hut on the edge of the snowfield","h":["h15"],"x":"Ryan crosses Grandmother Skaldi's palm with copper at a hut on the edge of the snowfield, and three cards come up: the Wheel of Fortune, the Five of Swords and the Hermit. Grandmother Skaldi says to…","k":"reading","id":"r73","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"Cards for Kev, read by Magister Quillon","at":"the Academy library","h":["h2"],"x":"Kev crosses Magister Quillon's palm with copper at the Academy library, and three cards come up: the Eight of Pentacles, the Page of Pentacles and the King of Pentacles. A good spread, all told.","k":"reading","id":"r77","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"the Reed and Rooster","at":"the road between Bleakmarsh and Carrbridge","h":["h12","h14","h18","h3"],"x":"Matt McF passes the Reed and Rooster, whose weathercock has been a reed for as long as anyone remembers, and Widow Orla Brack sweeps the step as if in a feud with it.","k":"road","id":"r72","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"On the road","at":"the road between Frosthold and Veldrock","h":["h15"],"x":"Ryan guesses 'a turnip' on the road to Veldrock and is right by sheer folly. The child is furious and gives him a ribbon anyway.","k":"road","id":"r74","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"Garrow's Span","at":"the road between Frosthold and Veldrock","h":["h15"],"x":"Ryan pays Old Garrow 3 copper at Garrow's Span, and Old Garrow chalks a mark on the rail for every foot that crosses.","k":"road","id":"r75","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"Met Doctor Fabian Loom","at":"the road between Ironhaven and Thornwall","h":["h17","h4"],"x":"Doctor Fabian Loom presses a free sample on Garrett 'for the road'. It tastes of pine and regret, and does nothing at all.","k":"road","id":"r79","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"the Mile-Warden's hut","at":"the road between Ironhaven and Thornwall","h":["h17","h4"],"x":"Garrett finds the first entry in the Mile-Warden's ledger is in a hand nobody knows, dated the day before the road was laid.","k":"road","id":"r80","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"Met Jory Bellwether","at":"the road between Carrbridge and Thornwall","h":["h17","h4"],"x":"Garrett is handed Jory Bellwether's handbell and asked to call the hour. The hour is not agreed upon, but the bell is a good one.","k":"road","id":"r62","d":19,"s":1,"sd":19,"imp":3,"score":30},{"t":"Met Tansy Fell","at":"the road between Carrbridge and Ironhaven","h":["h12","h14","h18","h3"],"x":"Varun helps Tansy Fell clear a barn. The ferrets do the work. Varun holds the sack and the lamp, and is thanked like a partner.","k":"road","id":"r70","d":19,"s":1,"sd":19,"imp":3,"score":30},{"t":"The Verdant Sigil vs 3 Skeletons and a Skeleton Archer","r":"won","at":"The Ashveil Crypts","h":["h6","h11","h19"],"tag":"dungeon","k":"fight","id":"f52","d":19,"s":1,"sd":19,"imp":2,"score":20,"x":"The Verdant Sigil runs into 3 Skeletons and a Skeleton Archer in the choir loft on the second floor of the Ashveil Crypts and comes out on top. The skeleton met Natasha's Smite and lay down for…"},{"t":"The Verdant Sigil vs 3 Skeletons and a Skeleton Archer","r":"won","at":"The Ashveil Crypts","h":["h6","h11","h19"],"tag":"dungeon","k":"fight","id":"f53","d":19,"s":1,"sd":19,"imp":2,"score":20,"x":"It's 3 Skeletons and a Skeleton Archer against the Verdant Sigil in the nave on the second floor of the Ashveil Crypts, and it isn't close. The hit of the day was Echo's Patient Shot on the…"},{"t":"Kev vs a Goblin Archer","r":"won","at":"Cragtooth Warren","h":["h2"],"tag":"camp","k":"fight","id":"f54","d":19,"s":1,"sd":19,"imp":2,"score":20,"x":"In the middle of the night, a Goblin Archer finds Kev's camp outside Cragtooth Warren, and Kev makes short work of it. The final blow was Kev's Ice Lance. Loot: 4 silver, 1 goblin ear."},{"t":"Pike, 58 cm","at":"by a stream outside The Wolf Den","h":["h16","h10"],"x":"Yomna cheers so loudly by a stream outside the Wolf Den that the whole bank looks over. Mikolaj bows and holds up a pike.","k":"catch","id":"c21","d":19,"s":1,"sd":19,"imp":1,"score":10},{"t":"Mushroom Pasty","at":"the Hollowood feast-day tables","h":["h16"],"x":"Mikolaj squeezes onto the end of a Hollowood feast-day bench for a Mushroom Pasty. It comes with a full account of the three mushrooms left out. (8 copper)","tag":"tavern","k":"meal","id":"m52","d":19,"s":1,"sd":19,"imp":1,"score":10},{"t":"Toll-Bridge Fritters","at":"judging the Carrbridge cooks' feud","h":["h12"],"x":"Matt McF tastes Toll-Bridge Fritters from the north-bank fritter stall, then from the south-bank fritter stall, then from the north-bank fritter stall again to be sure, and names the south-bank…","tag":"tavern","k":"meal","id":"m53","d":19,"s":1,"sd":19,"imp":1,"score":10},{"t":"Merchant's Honest Honey Cake","h":["h12"],"x":"Merchant's Honest Honey Cake at The Honest Toll: Matt McF cleans the plate. It is sticky in a way that follows you home. (1 silver 6 copper)","tag":"tavern","k":"meal","id":"m54","d":19,"s":1,"sd":19,"imp":1,"score":10},{"t":"Forager's Mushroom Stew","at":"by the road to Veldrock","h":["h5","h13","h9","h7"],"x":"Griffin tries some Forager's Mushroom Stew by the road to Veldrock. It goes wrong in a way nobody can quite explain, and everyone is a little unwell by morning.","tag":"camp","k":"meal","id":"m55","d":19,"s":1,"sd":19,"imp":1,"score":10},{"t":"\"Drinking With the Skeleton\" by the fire","at":"camp in The Ashveil Crypts","h":["h6","h19"],"x":"\"Drinking With the Skeleton\" by Echo: wobbly in the middle and grand at the end, with Christian carrying the chorus.","tag":"song","k":"night","id":"n14","d":19,"s":1,"sd":19,"imp":1,"score":10},{"t":"Cards for Claire, read by Magister Quillon","at":"the Academy library","h":["h9"],"x":"Claire crosses Magister Quillon's palm with copper at the Academy library, and three cards come up: the Ten of Cups, the Two of Swords and the Five of Wands. Magister Quillon turns the last card and…","k":"reading","id":"r65","d":19,"s":1,"sd":19,"imp":1,"score":10},{"t":"the Last Dry Sock","at":"the road between Cragtooth Warren and Ironhaven","h":["h1","h8"],"x":"Sam hangs their boots at the Last Dry Sock, where the rack has a rule: swap nothing, and sniff nothing.","k":"road","id":"r63","d":19,"s":1,"sd":19,"imp":1,"score":10},{"t":"the Last Dry Sock","at":"the road between Cragtooth Warren and Ironhaven","h":["h1","h8"],"x":"Spencer reads the wall of the Last Dry Sock, papered with rumour: lost parties, bounties, and in the biggest hand something about Emberdeep.","k":"road","id":"r64","d":19,"s":1,"sd":19,"imp":1,"score":10},{"t":"On the road","at":"the road between Ironhaven and Veldrock","h":["h13","h5","h7","h9"],"x":"Griffin tells a carter on the road to Veldrock a tall tale, and the carter turns out to know the real one. It is a long, red-eared mile.","k":"road","id":"r66","d":19,"s":1,"sd":19,"imp":1,"score":10},{"t":"Gant's toll bridge","at":"the road between Ironhaven and Veldrock","h":["h13","h5","h7","h9"],"x":"Griffin drops 2 copper in the toll box on the bridge, and the planks answer with a long, thoughtful creak.","k":"road","id":"r67","d":19,"s":1,"sd":19,"imp":1,"score":10},{"t":"Garrow's Span","at":"the road between Frosthold and Veldrock","h":["h15"],"x":"Ryan pays 3 copper at Garrow's Span, and the chalk mark on the rail is added to a long, wobbly row.","k":"road","id":"r68","d":19,"s":1,"sd":19,"imp":1,"score":10},{"t":"the Wolfwater ferry","at":"the road between Hollowood and The Wolf Den","h":["h10","h16"],"x":"Mikolaj holds the gunwale in the Wolfwater dark and counts the howls, and arrives dry and thoughtful.","k":"road","id":"r69","d":19,"s":1,"sd":19,"imp":1,"score":10},{"t":"the Four Stones","at":"the road between Carrbridge and Ironhaven","h":["h12","h14","h18","h3"],"x":"Matt McF runs a hand over the nearest pillar of the Four Stones, which is cool and smooth where countless hands have done the same.","k":"road","id":"r71","d":19,"s":1,"sd":19,"imp":1,"score":10},{"t":"Met Pim","at":"the road between Frosthold and Veldrock","h":["h15"],"x":"Pim insists on carrying Ryan's pack, and does it so well that Ryan almost forgets it was ever heavy.","k":"road","id":"r58","d":18,"s":1,"sd":18,"imp":3,"score":30},{"t":"Met Lady Perpetua Vane","at":"the road between Ironhaven and Redcrag Hills","h":["h1","h8"],"x":"Spencer follows Lady Perpetua Vane down the wrong road for half a day, because it would be rude not to.","k":"road","id":"r60","d":18,"s":1,"sd":18,"imp":3,"score":30},{"t":"Troll Haunch","h":["h7"],"x":"Robert orders a Troll Haunch at The Gilded Flagon before Madame Ostrava has finished saying it. His favourite kind of thing. (2 silver 7 copper)","tag":"tavern","k":"meal","id":"m46","d":18,"s":1,"sd":18,"imp":1,"score":10},{"t":"Toll-Bridge Fritters","at":"judging the Carrbridge cooks' feud","h":["h4"],"x":"Garrett is cornered by the north-bank fritter stall and the south-bank fritter stall in Carrbridge and made to taste both. the south-bank fritter stall wins, and the north-bank fritter stall demands…","tag":"tavern","k":"meal","id":"m47","d":18,"s":1,"sd":18,"imp":1,"score":10},{"t":"Drake Steak","h":["h12"],"x":"Matt McF has a Drake Steak at The Gilded Flagon, slowly, with the door open to the street. It makes the eater breathe tiny smoke rings. (3 silver 6 copper)","tag":"tavern","k":"meal","id":"m48","d":18,"s":1,"sd":18,"imp":1,"score":10},{"t":"Drake Steak","h":["h18"],"x":"Drake Steak is on the board at The Gilded Flagon this week, made from the drake flank Matt McF brought in. Mark orders it. It sizzles on the plate long after the fire's out. (3 silver 6 copper)","tag":"tavern","k":"meal","id":"m49","d":18,"s":1,"sd":18,"imp":1,"score":10},{"t":"Hammerhand Mixed Grill","h":["h1"],"x":"Sam orders a Hammerhand Mixed Grill at The Gilded Flagon. It arrives still hissing. (3 silver 5 copper)","tag":"tavern","k":"meal","id":"m50","d":18,"s":1,"sd":18,"imp":1,"score":10},{"t":"Walking-Cap Ragout","at":"the Ashveil Crypts","h":["h19","h6","h11"],"x":"Christian lays out some Walking-Cap Ragout in the Ashveil Crypts on a flat stone, like a proper table. It is rich, dark and only slightly mobile.","tag":"camp","k":"meal","id":"m51","d":18,"s":1,"sd":18,"imp":1,"score":10},{"t":"On the road","at":"the road between Ironhaven and Thornwall","h":["h13","h5","h7","h9"],"x":"Claire haggles over nothing in particular with a peddler on the road to Ironhaven, and leaves with nothing and a stiff neck.","k":"road","id":"r56","d":18,"s":1,"sd":18,"imp":1,"score":10},{"t":"On the road","at":"the road between Ashfen and Carrbridge","h":["h17","h4"],"x":"Garrett wants to adopt a stray duck on the road to Carrbridge. Chloe allows it, and the duck rides on a pack for six miles before being handed to a farm girl in return for a bun.","k":"road","id":"r57","d":18,"s":1,"sd":18,"imp":1,"score":10},{"t":"the Last Dry Sock","at":"the road between Cragtooth Warren and Ironhaven","h":["h12","h14","h18","h3"],"x":"The Last Dry Sock's stew has a name, a reputation and a regular complaint. Varun buys a bowl for 1 silver and finds the complaint is justified and the stew excellent.","k":"road","id":"r59","d":18,"s":1,"sd":18,"imp":1,"score":10},{"t":"On the road","at":"the road between The Ashveil Crypts and Hollowood","h":["h10","h16"],"x":"A grizzled old sellsword rests by the road to Hollowood and shares what the years taught. Yomna takes it in. It is worth a month's hard practice.","k":"road","id":"r61","d":18,"s":1,"sd":18,"imp":1,"score":10},{"t":"The Azure Stallions vs the Mimic King, a Cave Slime and a Drake","r":"won","at":"Cragtooth Warren","h":["h3","h12","h14","h18"],"tag":"dungeon","k":"fight","id":"f50","d":17,"s":1,"sd":17,"imp":5,"score":65,"x":"The long way down ends at the bottom of Cragtooth Warren, where the Azure Stallions kill the Mimic King, a Cave Slime and a Drake. Matt McF's Judgement closed it with a crackle, Varun's Chose the…"},{"t":"On the road","at":"the road between Ashfen and The Ashveil Crypts","h":["h17","h4"],"x":"A dragon crosses the sky above the road to Ashfen, so large that the day goes dark for a count of ten. Every beast and every traveller on the road falls flat. Chloe looks up.","k":"road","id":"r47","d":17,"s":1,"sd":17,"imp":4,"score":40},{"t":"Gruk's Victory Ham","at":"the Ashveil Crypts","h":["h19","h6","h11"],"x":"Gruk's Victory Ham in the Ashveil Crypts. Christian cooks it like a ceremony, and the crew eat it like one. It comes glazed on the warchief's own shield.","tag":"legendary","k":"meal","id":"m42","d":17,"s":1,"sd":17,"imp":3,"score":30},{"t":"Met the Fourth-Best Company","at":"the road between Ironhaven and Thornwall","h":["h13","h5","h7","h9"],"x":"Claire hears Captain Mabb of the Fourth-Best Company claiming her last kill in a roadside inn. The story has more dragons in it.","k":"road","id":"r54","d":17,"s":1,"sd":17,"imp":3,"score":30},{"t":"The Verdant Sigil vs 3 Skeletons and Risen Dead","r":"won","at":"The Ashveil Crypts","h":["h6","h11","h19"],"tag":"dungeon","k":"fight","id":"f49","d":17,"s":1,"sd":17,"imp":2,"score":20,"x":"It takes the Verdant Sigil 6 rounds to scrape past 3 Skeletons and Risen Dead in the coffin racks on the first floor of the Ashveil Crypts. Echo took the last shot with Thorn Whip, and it was…"},{"t":"Silver Roach, 15 cm","at":"by a stream in Redcrag Hills","h":["h1","h8"],"x":"Sam catches a silver roach by a stream in Redcrag Hills and tells it, kindly, that it has been very helpful.","k":"catch","id":"c20","d":17,"s":1,"sd":17,"imp":1,"score":10},{"t":"Kev vs a Kobold and a Giant Bat","r":"won","at":"Cragtooth Warren","h":["h2"],"tag":"dungeon","k":"fight","id":"f51","d":17,"s":1,"sd":17,"imp":1,"score":10,"x":"It's a Kobold and a Giant Bat against Kev in the humming roost on the first floor of Cragtooth Warren, and it isn't close. The last giant bat takes off and isn't seen again. Kev dealt with the…"},{"t":"Smoked Ice-Lake Salmon","h":["h17"],"x":"Chloe finds the Frosthold cart at the Ashfen market and tries some Smoked Ice-Lake Salmon, a long way from home. It is cut so thin the lamp shows through. (2 silver 2 copper)","tag":"tavern","k":"meal","id":"m39","d":17,"s":1,"sd":17,"imp":1,"score":10},{"t":"Thornwall Meat Pie","h":["h5"],"x":"Griffin follows his nose across Thornwall to a Thornwall Meat Pie. It holds its gravy like a moat holds water. (1 silver)","tag":"tavern","k":"meal","id":"m40","d":17,"s":1,"sd":17,"imp":1,"score":10},{"t":"Stolen-Sausage Hotpot","at":"by the road to Ironhaven","h":["h5","h13","h9","h7"],"x":"Griffin feeds the crew by the road to Ironhaven: some Stolen-Sausage Hotpot, and plenty of it. It tastes of justice and fennel.","tag":"camp","k":"meal","id":"m41","d":17,"s":1,"sd":17,"imp":1,"score":10},{"t":"Fish on Sticks","at":"by the road to Hollowood","h":["h16","h10"],"x":"Yomna scrapes the pot clean of Mikolaj's Fish on Sticks by the road to Hollowood and looks round for more. Yomna's favourite kind of thing.","tag":"camp","k":"meal","id":"m43","d":17,"s":1,"sd":17,"imp":1,"score":10},{"t":"Ration-Bag Hash","at":"Cragtooth Warren","h":["h14","h3","h12","h18"],"x":"Ankit cooks some Ration-Bag Hash in Cragtooth Warren and hands Varun the biggest bowl without a word. It crisps at the edges where the skillet was hottest.","tag":"camp","k":"meal","id":"m44","d":17,"s":1,"sd":17,"imp":1,"score":10},{"t":"Toasted Cheese Trenchers","at":"Redcrag Hills","h":["h1","h8"],"x":"Sam burns Toasted Cheese Trenchers in Redcrag Hills, then undercooks the second go. The crew spends a long night regretting both.","tag":"camp","k":"meal","id":"m45","d":17,"s":1,"sd":17,"imp":1,"score":10},{"t":"Cards for Garrett, read by Old Marrow","at":"a lean-to behind the undertaker's","h":["h4"],"x":"Old Marrow shuffles twice, cuts once, and deals Garrett three cards: the Ace of Wands, the Devil and the Eight of Pentacles. Old Marrow hums over the cards and won't commit.","k":"reading","id":"r49","d":17,"s":1,"sd":17,"imp":1,"score":10},{"t":"the Pickaxe Rest","at":"the road between The Collapsed Mine and Veldrock","h":["h15"],"x":"Ryan buys a miners' breakfast at the Pickaxe Rest for 1 silver: a Smoked Sausage Coil, black bread and a mug of tea strong enough to float a nail.","k":"road","id":"r46","d":17,"s":1,"sd":17,"imp":1,"score":10},{"t":"the Shrine of Quiet Names","at":"the road between Ashfen and The Ashveil Crypts","h":["h17","h4"],"x":"Garrett leaves 1 copper beside a row of stubs at the Shrine of Quiet Names and lights one more.","k":"road","id":"r48","d":17,"s":1,"sd":17,"imp":1,"score":10},{"t":"Hunting in Redcrag Hills","at":"Redcrag Hills","h":["h1","h8"],"x":"Sam insists on the creek path. Spencer insists on the ridge. Sam wins, and the creek turns out to be empty of everything but frogs.","tag":"hunt","k":"road","id":"r50","d":17,"s":1,"sd":17,"imp":1,"score":10},{"t":"Hunting in Redcrag Hills","at":"Redcrag Hills","h":["h1","h8"],"x":"Spencer has a soft spot for ground-nesting birds. The nest is marked on the map and then forgotten, on purpose.","tag":"hunt","k":"road","id":"r51","d":17,"s":1,"sd":17,"imp":1,"score":10},{"t":"Hunting in Redcrag Hills","at":"Redcrag Hills","h":["h1","h8"],"x":"Sam nods to the stranger at the edge of the light but does not move over. The stranger takes the hint and moves on. Sam sleeps with one hand on the pack.","tag":"hunt","k":"road","id":"r52","d":17,"s":1,"sd":17,"imp":1,"score":10},{"t":"the Toppled Chapel","at":"the road between The Ashveil Crypts and Hollowood","h":["h10","h16"],"x":"Yomna finds the fallen bell of the Toppled Chapel in the nettles and gives it a tap. It answers with a note that lasts too long.","k":"road","id":"r53","d":17,"s":1,"sd":17,"imp":1,"score":10},{"t":"the Mile-Warden's hut","at":"the road between Ironhaven and Thornwall","h":["h13","h5","h7","h9"],"x":"Sergeant Pellam hands Griffin a mug of tea at the Mile-Warden's hut that tastes of woodsmoke and a stern childhood.","k":"road","id":"r55","d":17,"s":1,"sd":17,"imp":1,"score":10},{"t":"The Royal Vigil vs a Skeleton Archer and a Skeleton","r":"won","at":"The Ashveil Crypts","h":["h10","h16"],"tag":"dungeon","k":"fight","id":"f47","d":16,"s":1,"sd":16,"imp":3,"score":30,"x":"A Skeleton Archer and a Skeleton meet The Royal Vigil in the bier hall on the second floor of the Ashveil Crypts, and don't last. Yomna cast Shock, and the skeleton did not get up. Loot: 4 bones.…"},{"t":"Met Ines","at":"the road between Cragtooth Warren and Redcrag Hills","h":["h2"],"x":"Kev is asked to check Ines's latest map. The compass rose is in the wrong corner, and the sea in the wrong place, but the hills are excellent.","k":"road","id":"r41","d":16,"s":1,"sd":16,"imp":3,"score":30},{"t":"Copper Whiskers vs 3 Bandit Archers and a Bandit","r":"won","at":"The King's Road","h":["h13","h9","h7","h5"],"tag":"road","k":"fight","id":"f48","d":16,"s":1,"sd":16,"imp":2,"score":20,"x":"In thick fog, Copper Whiskers handle 3 Bandit Archers and a Bandit on the road to Thornwall. Robert hung Expose Weakness on the bandit archer, and the crew followed the mark. Griffin timed Intercept…"},{"t":"Cards for Veronika, read by Aunt Crumb","at":"the back of the pie shop","h":["h13"],"x":"Aunt Crumb reads for Veronika at the back of the pie shop and takes a long look at each card: the Sun upside down, the Eight of Wands and the Knight of Swords. Aunt Crumb taps the middle card and…","k":"reading","id":"r45","d":16,"s":1,"sd":16,"imp":2,"score":20},{"t":"Hunting in Redcrag Hills","at":"Redcrag Hills","h":["h1","h8"],"x":"Spencer picks the patch half bare and stops. The rest is for the birds and the bears and the next one through.","tag":"hunt","k":"road","id":"r43","d":16,"s":1,"sd":16,"imp":2,"score":20},{"t":"Nothing bit","at":"by a stream in Redcrag Hills","h":["h1","h8"],"x":"Sam casts again and again by a stream in Redcrag Hills, and the water does nothing but ripple politely.","k":"catch","id":"c17","d":16,"s":1,"sd":16,"imp":1,"score":10},{"t":"Nothing bit","at":"by a stream in Redcrag Hills","h":["h8","h1"],"x":"Spencer reels in an empty hook by a stream in Redcrag Hills and looks at it as if it owes an explanation.","k":"catch","id":"c18","d":16,"s":1,"sd":16,"imp":1,"score":10},{"t":"Pale Loach, 13 cm","at":"the flooded gallery of the Collapsed Mine","h":["h15"],"x":"The night is quiet and the bite is slow, but Ryan lands a pale loach at the flooded gallery of the Collapsed Mine by the last candle.","k":"catch","id":"c19","d":16,"s":1,"sd":16,"imp":1,"score":10},{"t":"The Azure Stallions vs a Cave Troll","r":"won","at":"Cragtooth Warren","h":["h3","h12","h14","h18"],"tag":"dungeon","k":"fight","id":"f45","d":16,"s":1,"sd":16,"imp":1,"score":10,"x":"With Matt McF hitting hardest, the Azure Stallions beat a Cave Troll in the troll's hollow on the bottom floor of Cragtooth Warren. Last blow: Matt McF, with Mark of the Oath. Mark spent the whole…"},{"t":"The Azure Stallions vs a Drake","r":"won","at":"Cragtooth Warren","h":["h3","h12","h14","h18"],"tag":"dungeon","k":"fight","id":"f46","d":16,"s":1,"sd":16,"imp":1,"score":10,"x":"The Azure Stallions get the better of a Drake in the drake's warm cave on the bottom floor of Cragtooth Warren. Matt McF's Mark of the Oath came down once more, and that was that. When it got close,…"},{"t":"Rampart Hotpot","h":["h5"],"x":"Griffin has some Rampart Hotpot at The Sagging Beam and asks Old Hesk for the recipe. His favourite kind of thing. (1 silver 6 copper)","tag":"tavern","k":"meal","id":"m35","d":16,"s":1,"sd":16,"imp":1,"score":10},{"t":"Toasted Cheese Trenchers","at":"the Ashveil Crypts","h":["h11","h6","h19"],"x":"Natasha's Toasted Cheese Trenchers in the Ashveil Crypts come out the wrong colour. They eat them anyway. That was a mistake.","tag":"camp","k":"meal","id":"m36","d":16,"s":1,"sd":16,"imp":1,"score":10},{"t":"Wolf Stew","at":"the Ashveil Crypts","h":["h16","h10"],"x":"Supper in the Ashveil Crypts is some Wolf Stew. Mikolaj pretends not to watch everyone's faces. It is wolf, which nobody mentions to the horses.","tag":"camp","k":"meal","id":"m37","d":16,"s":1,"sd":16,"imp":1,"score":10},{"t":"Devilled Bat Wings","at":"the Collapsed Mine","h":["h15"],"x":"Ryan burns Devilled Bat Wings in the Collapsed Mine with nobody there to blame, which somehow makes it worse.","tag":"camp","k":"meal","id":"m38","d":16,"s":1,"sd":16,"imp":1,"score":10},{"t":"Brigid's toll bridge","at":"the road between Cragtooth Warren and Redcrag Hills","h":["h2"],"x":"Brigid Halm takes Kev's 3 copper toll and checks each coin against the light before the bar swings up.","k":"road","id":"r42","d":16,"s":1,"sd":16,"imp":1,"score":10},{"t":"the Three Hares crossroads","at":"the road between Hollowood and Thornwall","h":["h13","h5","h7","h9"],"x":"Claire comes to the Three Hares crossroads, where a post has three carved hares chasing their own ears and four ways to go.","k":"road","id":"r44","d":16,"s":1,"sd":16,"imp":1,"score":10},{"t":"Cards for Echo, read by Old Marrow","at":"a lean-to behind the undertaker's","h":["h6"],"x":"Echo crosses Old Marrow's palm with copper at a lean-to behind the undertaker's, and three cards come up: the Ten of Cups, the Seven of Cups and the Five of Wands. Nobody says anything for a while.","k":"reading","id":"r35","d":15,"s":1,"sd":15,"imp":3,"score":30},{"t":"Copper Whiskers vs a Rat Swarm, a Hedge Knight and a Bandit Archer","r":"won","at":"The King's Road","h":["h13","h9","h7","h5"],"tag":"camp","k":"fight","id":"f41","d":15,"s":1,"sd":15,"imp":2,"score":20,"x":"Riding a good week, Copper Whiskers beat a Rat Swarm, a Hedge Knight and a Bandit Archer at their camp on the road to Thornwall, in the middle of the night. The last rat swarm decides enough is…"},{"t":"The Azure Stallions vs 3 Kobold Slingers and 2 Kobolds","r":"won","at":"Cragtooth Warren","h":["h3","h12","h14","h18"],"tag":"dungeon","k":"fight","id":"f43","d":15,"s":1,"sd":15,"imp":2,"score":20,"x":"In the kobold nursery on the bottom floor of Cragtooth Warren, 3 Kobold Slingers and 2 Kobolds get in the Azure Stallions' way, briefly. Three of them went down together, and they have Matt McF's…"},{"t":"The Azure Stallions vs 2 Kobold Slingers, a Kobold and a Goblin Archer","r":"won","at":"Cragtooth Warren","h":["h3","h12","h14","h18"],"tag":"dungeon","k":"fight","id":"f44","d":15,"s":1,"sd":15,"imp":2,"score":20,"x":"Riding a good week, the Azure Stallions defeat 2 Kobold Slingers, a Kobold and a Goblin Archer in the chief's hall on the bottom floor of Cragtooth Warren. Ankit's Bless came at the right time for…"},{"t":"Rat-on-a-Stick","at":"the Ashveil Crypts","h":["h4","h17"],"x":"Garrett serves a Rat-on-a-Stick in the Ashveil Crypts and waits, spoon raised, for the verdict. It is the kind of thing nobody admits to liking, then has two.","tag":"camp","k":"meal","id":"m34","d":15,"s":1,"sd":15,"imp":2,"score":20},{"t":"Hunting in Redcrag Hills","at":"Redcrag Hills","h":["h1","h8"],"x":"A young buck is caught in a poacher's snare, frantic and bleeding at the hock. Spencer calms it, cuts the wire and steps back. The buck stands a moment, then is gone.","tag":"hunt","k":"road","id":"r40","d":15,"s":1,"sd":15,"imp":2,"score":20},{"t":"Brown Trout, 21 cm","at":"by a stream in Redcrag Hills","h":["h1","h8"],"x":"'Left a bit,' says Spencer. Sam moves left and lands a brown trout by a stream in Redcrag Hills. Spencer accepts the credit.","k":"catch","id":"c15","d":15,"s":1,"sd":15,"imp":1,"score":10},{"t":"Nothing bit","at":"by a stream in Redcrag Hills","h":["h2"],"x":"Something moves in the dark by a stream in Redcrag Hills, but it is not on the hook. Kev decides that is fine.","k":"catch","id":"c16","d":15,"s":1,"sd":15,"imp":1,"score":10},{"t":"Ryan vs 2 Kobold Slingers","r":"won","at":"The Collapsed Mine","h":["h15"],"tag":"dungeon","k":"fight","id":"f42","d":15,"s":1,"sd":15,"imp":1,"score":10,"x":"Two Kobold Slingers fall to Ryan in the ore-cart siding on the first floor of the Collapsed Mine. Ryan took the last shot with Pinning Shot, and it was enough. Loot: 21 silver, 2 ore, 3 kobold…"},{"t":"Forest-Floor Salad","at":"judging the Hollowood cooks' feud","h":["h13"],"x":"In the Hollowood feud over whether a salad counts as supper, Veronika is the deciding spoon this week. The vote goes to Ranger Holt. (1 silver)","tag":"tavern","k":"meal","id":"m31","d":15,"s":1,"sd":15,"imp":1,"score":10},{"t":"Mushroom Pasty","h":["h5"],"x":"Griffin finds a sunny step in Hollowood and takes his time over a Mushroom Pasty. It has seven kinds of mushroom and no regrets. (9 copper)","tag":"tavern","k":"meal","id":"m32","d":15,"s":1,"sd":15,"imp":1,"score":10},{"t":"Hedge Greens and Eggs","at":"by the road to Thornwall","h":["h5","h13","h9","h7"],"x":"Griffin makes Hedge Greens and Eggs by the road to Thornwall and nobody talks while they're eaten. They are better than the hedge they came out of.","tag":"camp","k":"meal","id":"m33","d":15,"s":1,"sd":15,"imp":1,"score":10},{"t":"\"The Bridge Is Falling\" by the fire","at":"camp in The Ashveil Crypts","h":["h16","h10"],"x":"Mikolaj starts \"The Bridge Is Falling\" quietly, and by the chorus Yomna is singing too.","tag":"song","k":"night","id":"n13","d":15,"s":1,"sd":15,"imp":1,"score":10},{"t":"the Shrine of the Footsore Saint","at":"the road between Hollowood and Thornwall","h":["h13","h5","h7","h9"],"x":"Claire nods at the Shrine of the Footsore Saint and passes by. Some saints are known for their patience.","k":"road","id":"r34","d":15,"s":1,"sd":15,"imp":1,"score":10},{"t":"On the road","at":"the road between Ashfen and The Ashveil Crypts","h":["h11","h19","h6"],"x":"Echo volunteers loudly to scout ahead on the road to the Ashveil Crypts, but Christian goes instead. The road beyond is clear, a heron is rude, and Christian returns to a band that's glad of the…","k":"road","id":"r36","d":15,"s":1,"sd":15,"imp":1,"score":10},{"t":"On the road","at":"the road between Redcrag Hills and Veldrock","h":["h2"],"x":"Kev returns a lost purse on the road to Redcrag Hills to a grateful pedlar, who presses 4 copper on him as a reward.","k":"road","id":"r37","d":15,"s":1,"sd":15,"imp":1,"score":10},{"t":"the Slag Heap Arms","at":"the road between Redcrag Hills and Veldrock","h":["h2"],"x":"Kev follows the black cinder path to the Slag Heap Arms, where Ulla Grint bangs a tin tray to call the shift in.","k":"road","id":"r38","d":15,"s":1,"sd":15,"imp":1,"score":10},{"t":"Hunting in Redcrag Hills","at":"Redcrag Hills","h":["h1","h8"],"x":"The wait is long and nothing breaks cover. Spencer finally stands to stretch and finds the thicket empty.","tag":"hunt","k":"road","id":"r39","d":15,"s":1,"sd":15,"imp":1,"score":10},{"t":"Cards for Spencer, read by Magister Quillon","at":"the Academy library","h":["h8"],"x":"Spencer queues at the Ironhaven omen fair for Magister Quillon, who reads at a trestle under a string of paper moons. Magister Quillon suggests a different day for anything important.","k":"reading","id":"r27","d":14,"s":1,"sd":14,"imp":2,"score":20},{"t":"Cards for themself","at":"The Damp Lantern","h":["h11"],"x":"With nobody else awake, Natasha lays out the Good Dog Tarot and reads for themself: the Three of Cups, the Moon and the Nine of Swords. Not a spread anyone wants.","k":"reading","id":"r33","d":14,"s":1,"sd":14,"imp":2,"score":20},{"t":"Nothing bit","at":"by a stream in Redcrag Hills","h":["h1","h8"],"x":"Sam nods off by a stream in Redcrag Hills with a rod in hand and wakes to a perfectly intact worm.","k":"catch","id":"c14","d":14,"s":1,"sd":14,"imp":1,"score":10},{"t":"Ryan vs a Kobold and a Kobold Slinger","r":"won","at":"The Collapsed Mine","h":["h15"],"tag":"dungeon","k":"fight","id":"f40","d":14,"s":1,"sd":14,"imp":1,"score":10,"x":"In the east stope on the first floor of the Collapsed Mine, a Kobold and a Kobold Slinger get in Ryan's way, briefly. The kobold was the last one standing until Ryan's Game Shot. Loot: 18 silver, 3…"},{"t":"Drake Steak","h":["h13"],"x":"A cart from Ironhaven has come for market day in Hollowood, selling a Drake Steak. Veronika buys one to see what the fuss is. It is half cooked before it ever meets the pan. (3 silver 6 copper)","tag":"tavern","k":"meal","id":"m22","d":14,"s":1,"sd":14,"imp":1,"score":10},{"t":"Mushroom Pasty","h":["h9"],"x":"Claire waits out the market-day crush in Hollowood for a Mushroom Pasty, trading gossip with the queue. It comes with a full account of the three mushrooms left out. (9 copper)","tag":"tavern","k":"meal","id":"m23","d":14,"s":1,"sd":14,"imp":1,"score":10},{"t":"Owl's-Nest Crumble","h":["h7"],"x":"Robert waits out the market-day crush in Hollowood for some Owl's-Nest Crumble, trading gossip with the queue. It crumbles exactly like a nest should. (1 silver 2 copper)","tag":"tavern","k":"meal","id":"m24","d":14,"s":1,"sd":14,"imp":1,"score":10},{"t":"Owl's-Nest Crumble","h":["h5"],"x":"Griffin eats some Owl's-Nest Crumble on the move through Hollowood, getting crumbs on everything. It has a marzipan egg that nobody wants to break first. (1 silver 2 copper)","tag":"tavern","k":"meal","id":"m25","d":14,"s":1,"sd":14,"imp":1,"score":10},{"t":"Ranger's Venison Haunch","h":["h7"],"x":"Ranger's Venison Haunch at The Watching Oak, and Robert orders a second before the first is finished. His favourite kind of thing. (3 silver 2 copper)","tag":"tavern","k":"meal","id":"m26","d":14,"s":1,"sd":14,"imp":1,"score":10},{"t":"Miner's Pasty","h":["h2"],"x":"Kev finds a sunny step in Veldrock and takes his time over a Miner's Pasty. It has a crust edge saved for the knockers, as is proper. (9 copper)","tag":"tavern","k":"meal","id":"m27","d":14,"s":1,"sd":14,"imp":1,"score":10},{"t":"Grey Bread with Dripping","h":["h2"],"x":"Kev queues for some Grey Bread with Dripping in Veldrock behind half the town. Worth it: it is grey, heavy and exactly right. (4 copper)","tag":"tavern","k":"meal","id":"m28","d":14,"s":1,"sd":14,"imp":1,"score":10},{"t":"Eel Pie","at":"judging the Ashfen cooks' feud","h":["h11"],"x":"Natasha tastes an Eel Pie from Widow Marl, then from Tobin the eel-catcher, then from Widow Marl again to be sure, and names Tobin the eel-catcher the better. The other one takes it badly. (1 silver)","tag":"tavern","k":"meal","id":"m29","d":14,"s":1,"sd":14,"imp":1,"score":10},{"t":"Toasted Cheese Trenchers","at":"the Ashveil Crypts","h":["h4","h17"],"x":"Garrett shoos everyone away from the pot in the Ashveil Crypts until Toasted Cheese Trenchers is ready. They drip cheese off the edge of the bread in the best way.","tag":"camp","k":"meal","id":"m30","d":14,"s":1,"sd":14,"imp":1,"score":10},{"t":"\"Venn's Candle\" by the fire","at":"camp in The Ashveil Crypts","h":["h16"],"x":"Mikolaj sings \"Venn's Candle\" by the fire. Nobody joins in, but nobody stops them either. Waffles yawns, loudly, in the second verse.","tag":"song","k":"night","id":"n11","d":14,"s":1,"sd":14,"imp":1,"score":10},{"t":"\"By the Light of the Moon\" by the fire","at":"camp in Cragtooth Warren","h":["h3","h14"],"x":"Varun sings \"By the Light of the Moon\" until the fire is embers, and Ankit hums along.","tag":"song","k":"night","id":"n12","d":14,"s":1,"sd":14,"imp":1,"score":10},{"t":"Met Sergeant Hobb Withy","at":"the road between Ironhaven and Redcrag Hills","h":["h1","h8"],"x":"Spencer finds Sergeant Hobb Withy again sitting on a milestone, polishing a button with great care and unseen devotion.","k":"road","id":"r28","d":14,"s":1,"sd":14,"imp":1,"score":10},{"t":"the Wolfwater ferry","at":"the road between Hollowood and The Wolf Den","h":["h13","h5","h7","h9"],"x":"Sedge poles Claire across the Wolfwater and waves off the coins until Claire insists, then pockets the 2 copper with a nod.","k":"road","id":"r29","d":14,"s":1,"sd":14,"imp":1,"score":10},{"t":"the Crooked Kettle","at":"the road between Hollowood and The Wolf Den","h":["h13","h5","h7","h9"],"x":"Griffin reaches the Crooked Kettle, where the antlers over the door are hung with dried herbs and a very old mitten.","k":"road","id":"r30","d":14,"s":1,"sd":14,"imp":1,"score":10},{"t":"the Pickaxe Rest","at":"the road between The Collapsed Mine and Veldrock","h":["h2"],"x":"A runaway ore cart rumbles down the track past the Pickaxe Rest, and Kev throws a plank under the wheels to stop it. The miners cheer.","k":"road","id":"r31","d":14,"s":1,"sd":14,"imp":1,"score":10},{"t":"the Leaning Mile","at":"the road between Ashfen and Carrbridge","h":["h11","h19","h6"],"x":"Echo stops at the Leaning Mile, the oldest marker between the dyke and the bridge, and finds a gap among the carved names.","k":"road","id":"r32","d":14,"s":1,"sd":14,"imp":1,"score":10},{"t":"Copper Whiskers vs 2 Wolves and Old Grizzlemaw","r":"won","at":"The Wolf Den","h":["h13","h9","h7","h5"],"tag":"dungeon","k":"fight","id":"f37","d":13,"s":1,"sd":13,"imp":5,"score":65,"x":"Two Wolves and Old Grizzlemaw held the bottom of the Wolf Den long enough: Copper Whiskers kill them. Griffin's Intercept took the worst of it, Claire's Smite turned it back, Veronika kept swinging…"},{"t":"Grizzlemaw Honey Cakes","at":"the Wolf Den","h":["h5","h13","h9","h7"],"x":"Nobody keeps watch in the Wolf Den while Griffin cooks Grizzlemaw Honey Cakes. Nothing would dare interrupt. They taste of forty summers.","tag":"legendary","k":"meal","id":"m19","d":13,"s":1,"sd":13,"imp":3,"score":30},{"t":"Met Sergeant Hobb Withy","at":"the road between Ironhaven and The King's Road","h":["h1","h8"],"x":"Sergeant Hobb Withy puts Spencer through a roadside drill: stand, turn, kneel, rise. Spencer comes out of it standing straighter, and humbled.","k":"road","id":"r25","d":13,"s":1,"sd":13,"imp":3,"score":30},{"t":"Pale Loach, 22 cm","at":"the flooded gallery of the Collapsed Mine","h":["h15"],"x":"Ryan adds a new name to the league's catch book at the flooded gallery of the Collapsed Mine: Pale Loach, 22 cm, never taken before.","k":"catch","id":"c12","d":13,"s":1,"sd":13,"imp":2,"score":20},{"t":"Stolen-Sausage Hotpot","at":"the Carrbridge feast-day tables","h":["h6"],"x":"Feast day in Carrbridge: the cook has made Stolen-Sausage Hotpot from the parts heroes sold here this season, and Echo gets the first bowl. It is all the sweeter for being stolen twice. (8 copper)","tag":"tavern","k":"meal","id":"m17","d":13,"s":1,"sd":13,"imp":2,"score":20},{"t":"Wolf Stew","at":"the Ashveil Crypts","h":["h16","h10"],"x":"Mikolaj lays out some Wolf Stew in the Ashveil Crypts on a flat stone, like a proper table. It keeps everyone warm all night.","tag":"camp","k":"meal","id":"m20","d":13,"s":1,"sd":13,"imp":2,"score":20},{"t":"Checkers: Chloe v Garrett","at":"camp in The Ashveil Crypts","h":["h17","h4"],"x":"Garrett pushes the first piece forward with one finger, and Chloe answers with a grin. Garrett walked into a double jump and now stares at the board in dignified grief. Garrett holds up a single…","tag":"checkers","k":"night","id":"n10","d":13,"s":1,"sd":13,"imp":2,"score":20},{"t":"The one that got away","at":"by a stream on the road to Ashfen","h":["h6","h11","h19"],"x":"Echo loses a bog eel by a stream on the road to Ashfen at the last second and spends the evening describing the exact angle.","k":"catch","id":"c11","d":13,"s":1,"sd":13,"imp":1,"score":10},{"t":"Blind Cavefish, 9 cm","at":"the flooded gallery of the Collapsed Mine","h":["h2"],"x":"A lantern, a thermos and a long, still night: Kev lands a blind cavefish at the flooded gallery of the Collapsed Mine just before the stars tire.","k":"catch","id":"c13","d":13,"s":1,"sd":13,"imp":1,"score":10},{"t":"The Azure Stallions vs 2 Kobold Slingers and a Kobold","r":"won","at":"Cragtooth Warren","h":["h3","h12","h14","h18"],"tag":"dungeon","k":"fight","id":"f38","d":13,"s":1,"sd":13,"imp":1,"score":10,"x":"It's 2 Kobold Slingers and a Kobold against the Azure Stallions in the sentry hole on the first floor of Cragtooth Warren, and it isn't close. Varun put Hunter's Mark on the kobold slinger, and…"},{"t":"Ryan vs 2 Giant Rats","r":"won","at":"The Collapsed Mine","h":["h15"],"tag":"dungeon","k":"fight","id":"f39","d":13,"s":1,"sd":13,"imp":1,"score":10,"x":"Ryan runs into 2 Giant Rats in the main drift on the first floor of the Collapsed Mine and comes out on top. The last giant rat turns tail. The giant rat had been trouble right up until Ryan's Game…"},{"t":"Stolen-Sausage Hotpot","at":"the Carrbridge feast-day tables","h":["h11"],"x":"The Carrbridge cook serves Stolen-Sausage Hotpot on feast day, made from what heroes sold her, and Natasha recognises some of it. It tastes of justice and fennel. (8 copper)","tag":"tavern","k":"meal","id":"m18","d":13,"s":1,"sd":13,"imp":1,"score":10},{"t":"Ration-Bag Hash","at":"Cragtooth Warren","h":["h14","h3","h12","h18"],"x":"Ankit serves some Ration-Bag Hash in Cragtooth Warren, and Varun closes his eyes on the first mouthful. A favourite. It turns out better than the ration bag had any right to.","tag":"camp","k":"meal","id":"m21","d":13,"s":1,"sd":13,"imp":1,"score":10},{"t":"the Ashfen ferry","at":"the road between Ashfen and Carrbridge","h":["h11","h19","h6"],"x":"The crossing at the Ashfen ferry has a bait tin hung on the post and a sign asking travellers to leave a little for the next angler. Christian adds a worm to the tin.","k":"road","id":"r23","d":13,"s":1,"sd":13,"imp":1,"score":10},{"t":"On the road","at":"the road between Ashfen and Carrbridge","h":["h11","h19","h6"],"x":"A path through the meadows shortens the road to Ashfen by half a mile. Natasha takes it with a clear conscience and a stalk of grass between the teeth.","k":"road","id":"r24","d":13,"s":1,"sd":13,"imp":1,"score":10},{"t":"Tinker's Ford","at":"the road between Ironhaven and The King's Road","h":["h1","h8"],"x":"Sam loses the race to cross Tinker's Ford with a splash that startles the heron into leaving.","k":"road","id":"r26","d":13,"s":1,"sd":13,"imp":1,"score":10},{"t":"Deep Gulper, 64 cm","at":"the flooded gallery of the Collapsed Mine","h":["h2"],"x":"A first for the whole league: Kev pulls a deep gulper at the flooded gallery of the Collapsed Mine and holds it up as proof.","k":"catch","id":"c10","d":12,"s":1,"sd":12,"imp":2,"score":20},{"t":"The Azure Stallions vs 3 Kobolds and a Giant Bat","r":"won","at":"Cragtooth Warren","h":["h3","h12","h14","h18"],"tag":"dungeon","k":"fight","id":"f35","d":12,"s":1,"sd":12,"imp":2,"score":20,"x":"With Mark hitting hardest, the Azure Stallions make short work of 3 Kobolds and a Giant Bat in the bat roost on the first floor of Cragtooth Warren. One more Hunter's Mark from Mark, and the kobold…"},{"t":"The Azure Stallions vs 3 Kobold Slingers and 2 Goblin Archers","r":"won","at":"Cragtooth Warren","h":["h3","h12","h14","h18"],"tag":"dungeon","k":"fight","id":"f36","d":12,"s":1,"sd":12,"imp":2,"score":20,"x":"The Azure Stallions see off 3 Kobold Slingers and 2 Goblin Archers in the slingers' gallery on the first floor of Cragtooth Warren. The fight ended in a flash of Matt McF's Smite. Loot: 9 silver…"},{"t":"Cards for Christian, read by Sabine Venn","at":"the toll-house parlour","h":["h19"],"x":"At the toll-house parlour, Sabine Venn turns Christian's three cards one at a time: the Two of Cups, the High Priestess and Temperance. Even the candle seems to approve.","k":"reading","id":"r22","d":12,"s":1,"sd":12,"imp":2,"score":20},{"t":"Nothing bit","at":"under Carrbridge","h":["h6"],"x":"The float sits still under Carrbridge. So does Echo. Neither moves for a very long time.","k":"catch","id":"c8","d":12,"s":1,"sd":12,"imp":1,"score":10},{"t":"Stolen from the bank","at":"the King's Road ford","h":["h1","h8"],"x":"an otter follows Sam along the bank at the King's Road ford all morning, and finally gets a silver roach. Persistence is rewarded.","k":"catch","id":"c9","d":12,"s":1,"sd":12,"imp":1,"score":10},{"t":"Ryan vs a Giant Spider","r":"won","at":"The Collapsed Mine","h":["h15"],"tag":"dungeon","k":"fight","id":"f34","d":12,"s":1,"sd":12,"imp":1,"score":10,"x":"A Giant Spider falls to Ryan in the new tunnels on the first floor of the Collapsed Mine. Ryan's Game Shot finished the fight."},{"t":"Fish on Sticks","at":"the Ashveil Crypts","h":["h16","h10"],"x":"Mikolaj makes Fish on Sticks in the Ashveil Crypts, mostly for Yomna, who knows it and is very pleased. They stood round the fire like guests.","tag":"camp","k":"meal","id":"m14","d":12,"s":1,"sd":12,"imp":1,"score":10},{"t":"The Sergeant's Roast","at":"the Thornwall feast-day tables","h":["h6"],"x":"Echo squeezes onto the end of a Thornwall feast-day bench for The Sergeant's Roast. It is carved square, because the sergeant's cousin can't do it any other way. (8 copper)","tag":"tavern","k":"meal","id":"m15","d":12,"s":1,"sd":12,"imp":1,"score":10},{"t":"The Sergeant's Roast","at":"the Thornwall feast-day tables","h":["h11"],"x":"Feast day in Thornwall: Natasha finds a bench at the long tables and eats The Sergeant's Roast with strangers who are friends by the pudding. It comes with the carving shouted out slice by slice. (8…","tag":"tavern","k":"meal","id":"m16","d":12,"s":1,"sd":12,"imp":1,"score":10},{"t":"Chess: Mikolaj v Yomna","at":"camp in The Ashveil Crypts","h":["h16","h10"],"x":"Yomna is a queen up by move 25, and Mikolaj doesn't need to see the rest. Yomna and Mikolaj shake hands over the Pocket Peg Chess, and the tally begins. Mikolaj loses and so keeps the fire company…","tag":"chess","k":"night","id":"n8","d":12,"s":1,"sd":12,"imp":1,"score":10},{"t":"\"Nobody Thought We'd Win\" by the fire","at":"camp in Cragtooth Warren","h":["h3"],"x":"Varun sings \"Nobody Thought We'd Win\" to the fire. The fire is a forgiving audience.","tag":"song","k":"night","id":"n9","d":12,"s":1,"sd":12,"imp":1,"score":10},{"t":"On the road","at":"the road between The Ashveil Crypts and Hollowood","h":["h10","h16"],"x":"Mikolaj leaves a cottage on the road to the Ashveil Crypts with a full belly and a recipe for Wild Onion Broth that no one has written down in sixty years. He says it twice, to keep it.","k":"road","id":"r17","d":12,"s":1,"sd":12,"imp":1,"score":10},{"t":"Hunting in The King's Road","at":"The King's Road","h":["h1","h8"],"x":"Sam is still a dozen yards short when the vixen whisks into the earth, and the den falls silent. A clear conscience, and an empty pack.","tag":"hunt","k":"road","id":"r18","d":12,"s":1,"sd":12,"imp":1,"score":10},{"t":"Hunting in The King's Road","at":"The King's Road","h":["h1","h8"],"x":"Spencer wants to push on, and Sam says to wait a little longer. They wait. The ferns shift, and the crew's patience is repaid at about the same moment Spencer runs out of it.","tag":"hunt","k":"road","id":"r19","d":12,"s":1,"sd":12,"imp":1,"score":10},{"t":"the Miller's Tankard","at":"the road between Carrbridge and Thornwall","h":["h11","h19","h6"],"x":"Goodwife Brannoch shows Natasha through the old mill under the Miller's Tankard, past the great stones and the cat who runs them.","k":"road","id":"r20","d":12,"s":1,"sd":12,"imp":1,"score":10},{"t":"On the road","at":"the road between Carrbridge and Thornwall","h":["h11","h19","h6"],"x":"The scarecrow's farmer overhears Echo's side of the conversation and is moved. Apples change hands.","k":"road","id":"r21","d":12,"s":1,"sd":12,"imp":1,"score":10},{"t":"Ryan vs a Giant Bat and a Giant Rat","r":"won","at":"The Collapsed Mine","h":["h15"],"tag":"dungeon","k":"fight","id":"f33","d":11,"s":1,"sd":11,"imp":3,"score":30,"x":"Ryan's first blood comes in the pithead on the first floor of the Collapsed Mine: a Giant Bat and a Giant Rat, handled. Loot: a pair of bat wings, 1 fang."},{"t":"Met Jory Bellwether","at":"the road between Cragtooth Warren and Ironhaven","h":["h12","h14","h18","h3"],"x":"'Oyez!' says Jory Bellwether to Mark, and tells the road a piece of news about the Collapsed Mine that Mark very much wanted to hear.","k":"road","id":"r13","d":11,"s":1,"sd":11,"imp":3,"score":30},{"t":"On the road","at":"the road between Goblin Camp and Thornwall","h":["h11","h19","h6"],"x":"A torn treasure map blows across the road to Thornwall and wraps around Natasha's ankle. It is faded, but Emberdeep is clearly marked.","k":"road","id":"r15","d":11,"s":1,"sd":11,"imp":3,"score":30},{"t":"Pike, 78 cm","at":"the King's Road ford","h":["h1","h8"],"x":"Sam catches a pike at the King's Road ford, the league's very first, and the bank applauds like it was planned.","k":"catch","id":"c5","d":11,"s":1,"sd":11,"imp":2,"score":20},{"t":"Blind Cavefish, 10 cm","at":"the flooded gallery of the Collapsed Mine","h":["h2"],"x":"Kev adds a new name to the league's catch book at the flooded gallery of the Collapsed Mine: Blind Cavefish, 10 cm, never taken before.","k":"catch","id":"c7","d":11,"s":1,"sd":11,"imp":2,"score":20},{"t":"Copper Whiskers vs 4 Dire Wolves and a Wolf","r":"won","at":"The Wolf Den","h":["h13","h9","h7","h5"],"tag":"dungeon","k":"fight","id":"f31","d":11,"s":1,"sd":11,"imp":2,"score":20,"x":"In the whelping hollow on the first floor of the Wolf Den, Copper Whiskers see off 4 Dire Wolves and a Wolf. Taunt from Griffin kept the back row out of it. Robert took the worst corner of the fight…"},{"t":"Silver Roach, 25 cm","at":"the King's Road ford","h":["h1","h8"],"x":"Everyone on the bank at the King's Road ford stops talking as Sam lifts a silver roach of 25 cm clear of the water.","k":"catch","id":"c6","d":11,"s":1,"sd":11,"imp":1,"score":10},{"t":"The Cobalt Storm vs 2 Giant Rats and a Skeleton","r":"won","at":"The Ashveil Crypts","h":["h17","h4"],"tag":"dungeon","k":"fight","id":"f32","d":11,"s":1,"sd":11,"imp":1,"score":10,"x":"In the gatehouse on the first floor of the Ashveil Crypts, 2 Giant Rats and a Skeleton get in the Cobalt Storm's way, briefly. Garrett's Quick Shot was where the fight changed hands. Loot: 3 bones,…"},{"t":"Wolf Stew","at":"the Wolf Den","h":["h5","h13","h9","h7"],"x":"Supper in the Wolf Den is some Wolf Stew, by Griffin. It tastes of a long day and a good fire.","tag":"camp","k":"meal","id":"m13","d":11,"s":1,"sd":11,"imp":1,"score":10},{"t":"\"Venn's Candle\" by the fire","at":"camp by the road to The Ashveil Crypts","h":["h16","h10"],"x":"Mikolaj means every word of \"Venn's Candle\" and misses about a third of the notes. Nobody minds the notes.","tag":"song","k":"night","id":"n6","d":11,"s":1,"sd":11,"imp":1,"score":10},{"t":"Chess: Mark v Ankit","at":"camp in Cragtooth Warren","h":["h18","h14"],"x":"Mark pushes a pawn forward two squares and looks very pleased about it. Mark leaves the queen where anything could take it on move 7, and Ankit does. Move 52: Ankit says 'mate' very quietly, and…","tag":"chess","k":"night","id":"n7","d":11,"s":1,"sd":11,"imp":1,"score":10},{"t":"the Last Dry Sock","at":"the road between Cragtooth Warren and Ironhaven","h":["h12","h14","h18","h3"],"x":"Varun reads the notice board of the Last Dry Sock, where somebody has written 'ask about the dry ones' and been ignored.","k":"road","id":"r14","d":11,"s":1,"sd":11,"imp":1,"score":10},{"t":"the Toppled Chapel","at":"the road between The Ashveil Crypts and Hollowood","h":["h10","h16"],"x":"A hollow in the wall of the Toppled Chapel holds a pilgrim's small hoard, 6 silver in a pouch. Mikolaj leaves a prayer in its place.","k":"road","id":"r16","d":11,"s":1,"sd":11,"imp":1,"score":10},{"t":"Brown Trout, 23 cm","at":"the King's Road ford","h":["h1","h8"],"x":"Nobody in the league has landed a brown trout before, and now Sam has, at the King's Road ford. A first.","k":"catch","id":"c4","d":10,"s":1,"sd":10,"imp":2,"score":20},{"t":"Copper Whiskers vs 3 Dire Wolves","r":"won","at":"The Wolf Den","h":["h13","h9","h7","h5"],"tag":"camp","k":"fight","id":"f30","d":10,"s":1,"sd":10,"imp":2,"score":20,"x":"With Griffin holding the line, Copper Whiskers beat 3 Dire Wolves at their camp on the first floor of the Wolf Den, in the middle of the night. The last dire wolf turns tail. Veronika put Hunter's…"},{"t":"Cards for Mark, read by Magister Quillon","at":"the Academy library","h":["h18"],"x":"Magister Quillon reads for Mark at the Academy library and takes a long look at each card: the Knight of Pentacles, Justice and the Seven of Wands. Magister Quillon smiles at the last card.","k":"reading","id":"r12","d":10,"s":1,"sd":10,"imp":2,"score":20},{"t":"Silver Roach, 16 cm","at":"by a stream on the road to The Ashveil Crypts","h":["h16","h10"],"x":"Mikolaj lands a silver roach by a stream on the road to the Ashveil Crypts while Yomna offers advice from the bank. The advice is not taken, and the fish is caught anyway.","k":"catch","id":"c3","d":10,"s":1,"sd":10,"imp":1,"score":10},{"t":"Sam's Pack vs 2 Bandits","r":"won","at":"The King's Road","h":["h1","h8"],"tag":"wild","k":"fight","id":"f27","d":10,"s":1,"sd":10,"imp":1,"score":10,"x":"In thick fog, Sam's Pack handles 2 Bandits on the King's Road. Sam was everywhere at once. Loot: 15 silver each, 1 bag of stolen goods."},{"t":"Copper Whiskers vs 3 Wolves","r":"won","at":"The Wolf Den","h":["h13","h9","h7","h5"],"tag":"dungeon","k":"fight","id":"f28","d":10,"s":1,"sd":10,"imp":1,"score":10,"x":"Three Wolves make the mistake of going for Copper Whiskers in the bone yard on the first floor of the Wolf Den. The last wolf is gone before anyone can stop it. It was Veronika's Hunter's Mark that…"},{"t":"Copper Whiskers vs a Dire Wolf","r":"won","at":"The Wolf Den","h":["h13","h9","h7","h5"],"tag":"dungeon","k":"fight","id":"f29","d":10,"s":1,"sd":10,"imp":1,"score":10,"x":"Copper Whiskers handle a Dire Wolf in the kill ground on the first floor of the Wolf Den. Claire landed Smite on the dire wolf hard enough to hear from the back. Loot: 2 pelts, 2 fangs & claws, 3…"},{"t":"Forge-Bellows Pepper Pot","h":["h14"],"x":"Madame Ostrava talks Ankit into a Forge-Bellows Pepper Pot at The Gilded Flagon. Good advice: it has a ladle that has never been to the bottom. (2 silver 2 copper)","tag":"tavern","k":"meal","id":"m10","d":10,"s":1,"sd":10,"imp":1,"score":10},{"t":"Toasted Cheese Trenchers","at":"the Wolf Den","h":["h5","h13","h9","h7"],"x":"Griffin has the fire going early in the Wolf Den, and by dark the crew is eating Toasted Cheese Trenchers. They drip cheese off the edge of the bread in the best way.","tag":"camp","k":"meal","id":"m11","d":10,"s":1,"sd":10,"imp":1,"score":10},{"t":"Hammerhand Mixed Grill","h":["h3","h12","h18"],"x":"Varun, Matt McF and Mark order a Hammerhand Mixed Grill for the table at The Gilded Flagon and eat it in reverent silence. It has a bit of everything the butcher had, and one thing nobody can name.…","tag":"tavern","k":"meal","id":"m12","d":10,"s":1,"sd":10,"imp":1,"score":10},{"t":"\"The Washing-Line Jig\" by the fire","at":"camp in Goblin Camp","h":["h6","h19"],"x":"Echo sings \"The Washing-Line Jig\" and loses the tune twice. Each time Christian hands it back.","tag":"song","k":"night","id":"n4","d":10,"s":1,"sd":10,"imp":1,"score":10},{"t":"Chess: Ankit v Varun","at":"The Gilded Flagon","h":["h14","h3"],"x":"Checkmate on move 24, by Ankit's rook, and Varun stares at the board for a long while. Ankit and Varun play for the first time, and already both are keeping score.","tag":"chess","k":"night","id":"n5","d":10,"s":1,"sd":10,"imp":1,"score":10},{"t":"the Four Stones","at":"the road between Carrbridge and Ironhaven","h":["h12","h14","h18","h3"],"x":"At the Four Stones Mark picks the road with fewest footprints, and is rewarded with a clear sky and a quiet mile.","k":"road","id":"r10","d":10,"s":1,"sd":10,"imp":1,"score":10},{"t":"the Four Stones","at":"the road between Carrbridge and Ironhaven","h":["h12","h14","h18","h3"],"x":"Ankit adds a pebble to the pile at the Four Stones, as the custom runs, and the pile grows by one.","k":"road","id":"r11","d":10,"s":1,"sd":10,"imp":1,"score":10},{"t":"The Verdant Sigil vs Gruk the Warchief, a Goblin Archer and a Goblin","r":"won","at":"Goblin Camp","h":["h6","h11","h19"],"tag":"dungeon","k":"fight","id":"f25","d":9,"s":1,"sd":9,"imp":5,"score":224,"x":"Down at the bottom of Goblin Camp, The Verdant Sigil slays Gruk the Warchief, a Goblin Archer and a Goblin. Echo's Pinning Shot dropped Gruk, Christian's Hammer Down tied him up, and Echo did the…"},{"t":"Copper Whiskers vs 2 Dire Wolves and a Wolf","r":"won","at":"The Wolf Den","h":["h13","h9","h7","h5"],"tag":"camp","k":"fight","id":"f24","d":9,"s":1,"sd":9,"imp":3,"score":30,"x":"In the middle of the night at their camp in the Wolf Den, Copper Whiskers make short work of 2 Dire Wolves and a Wolf. Veronika drew, held and let Hunter's Mark go, and the dire wolf never saw it;…"},{"t":"Checkers: Garrett v Chloe","at":"camp in The Ashveil Crypts","h":["h4","h17"],"x":"Garrett runs out of safe squares, and Chloe wins without so much as a flourish. Record opened: Chloe against Garrett, at checkers, with a long road ahead. First watch is Garrett's, by the terms of…","tag":"checkers","k":"night","id":"n3","d":9,"s":1,"sd":9,"imp":3,"score":30},{"t":"Copper Whiskers vs 4 Wolves","r":"won","at":"The Wolf Den","h":["h13","h9","h7","h5"],"tag":"dungeon","k":"fight","id":"f23","d":9,"s":1,"sd":9,"imp":2,"score":20,"x":"Copper Whiskers cut down 4 Wolves on floor 1 of the Wolf Den. The wolf had been trouble right up until Veronika's Hunter's Mark. Griffin kept everyone standing (3 healed). Loot: 3 pelts, 3 fangs &…"},{"t":"Kev vs a Kobold Slinger and a Kobold","r":"won","at":"The Collapsed Mine","h":["h2"],"tag":"dungeon","k":"fight","id":"f26","d":9,"s":1,"sd":9,"imp":2,"score":20,"x":"Kev wraps what's left of the kobold slinger in an old blanket and ties it to his pack. The crows watch with professional interest."},{"t":"Cards for Varun, read by Sabine Venn","at":"the toll-house parlour","h":["h3"],"x":"At the toll-house parlour, Sabine Venn turns Varun's three cards one at a time: the Chariot, the King of Wands and the Page of Pentacles. A good spread, all told.","k":"reading","id":"r9","d":9,"s":1,"sd":9,"imp":2,"score":20},{"t":"Walking-Cap Ragout","h":["h12"],"x":"The market in Carrbridge has a cook up from Ashfen today. Matt McF queues for some Walking-Cap Ragout on the strength of the smell alone. It has one mushroom in it that is still trying to leave. (2…","tag":"tavern","k":"meal","id":"m7","d":9,"s":1,"sd":9,"imp":1,"score":10},{"t":"Fen-Mist Chowder","at":"the Ashfen feast-day tables","h":["h4"],"x":"Garrett eats some Fen-Mist Chowder at the Ashfen feast-day tables, elbow to elbow with the whole town. It smells of smoke and the fen at dawn. (8 copper)","tag":"tavern","k":"meal","id":"m8","d":9,"s":1,"sd":9,"imp":1,"score":10},{"t":"Hedge Greens and Eggs","at":"on the King's Road","h":["h8","h1"],"x":"Spencer cooks Hedge Greens and Eggs on the King's Road. They are better than the hedge they came out of.","tag":"camp","k":"meal","id":"m9","d":9,"s":1,"sd":9,"imp":1,"score":10},{"t":"Copper Whiskers vs 4 Wolves","r":"won","at":"The Greenwood","h":["h13","h9","h7","h5"],"tag":"road","k":"fight","id":"f18","d":8,"s":1,"sd":8,"imp":3,"score":30,"x":"Copper Whiskers see off 4 Wolves on the road to the Wolf Den, and the last one bolts. Griffin's Hold the Line came at the right time for all of them; Veronika and Clementine the cat found the way…"},{"t":"Kev vs 2 Giant Bats","r":"won","at":"The Collapsed Mine","h":["h2"],"tag":"dungeon","k":"fight","id":"f20","d":8,"s":1,"sd":8,"imp":3,"score":30,"x":"First blood for Kev, who sees off 2 Giant Bats on floor 1 of the Collapsed Mine. Loot: 1 fang and a pair of bat wings."},{"t":"The Azure Stallions vs 3 Bandit Captains, a Bandit and a Bandit Archer","r":"won","at":"The King's Road","h":["h3","h12","h14","h18"],"tag":"wild","k":"fight","id":"f22","d":8,"s":1,"sd":8,"imp":3,"score":30,"x":"After nearly dying on the King's Road, Matt McF is more careful now (risk tolerance: prudent → careful)."},{"t":"Silver Roach, 30 cm","at":"the King's Road ford","h":["h14","h3","h12","h18"],"x":"The books show no Silver Roach until today, when Ankit lands one at the King's Road ford.","k":"catch","id":"c1","d":8,"s":1,"sd":8,"imp":2,"score":20},{"t":"The Cobalt Storm vs 2 Bounty Hunters and the Bounty Hunters' Captain","r":"won","at":"The King's Road","h":["h17","h4"],"tag":"bounty","k":"fight","id":"f19","d":8,"s":1,"sd":8,"imp":2,"score":20,"x":"The Cobalt Storm handles 2 Bounty Hunters and the Bounty Hunters' Captain on the road out of Carrbridge, sent for the price on Garrett's head. The fight turned on Chloe's Volley. Chloe pulled a…"},{"t":"The Azure Stallions vs 3 Bandits, a Bandit Archer and a Bandit Captain","r":"won","at":"The King's Road","h":["h3","h12","h14","h18"],"tag":"wild","k":"fight","id":"f21","d":8,"s":1,"sd":8,"imp":2,"score":20,"x":"The Azure Stallions handle 3 Bandits, a Bandit Archer and a Bandit Captain on the King's Road. Varun's Volley fell on four of them like hail. Loot: 7 stolen goods, 4 bandit sausages, 2 rations."},{"t":"Devilled Bat Wings","at":"the Collapsed Mine","h":["h2"],"x":"Kev's Devilled Bat Wings go wrong in the Collapsed Mine. There's nobody to say so, but the smell says it for them.","tag":"camp","k":"meal","id":"m6","d":8,"s":1,"sd":8,"imp":2,"score":20},{"t":"Nothing bit","at":"the King's Road ford","h":["h14","h3","h12","h18"],"x":"Ankit waits for the moon to do something helpful at the King's Road ford. It does not.","k":"catch","id":"c2","d":8,"s":1,"sd":8,"imp":1,"score":10},{"t":"\"Acorn Ale\" by the fire","at":"camp in The Wolf Den","h":["h13"],"x":"\"Acorn Ale\" turns into a contest to see who can sing it loudest. Everyone loses, especially the owls. Clementine leaves at the first note and does not come back till breakfast.","tag":"song","k":"night","id":"n2","d":8,"s":1,"sd":8,"imp":1,"score":10},{"t":"Sam vs a Bandit and a Bandit Captain","r":"lost","at":"The King's Road","h":["h1"],"tag":"wild","k":"fight","id":"f15","d":7,"s":1,"sd":7,"imp":3,"score":30,"x":"On the King's Road, Sam is routed by a Bandit and a Bandit Captain and runs for it. Injured: Sam (sprained ankle)."},{"t":"Spencer vs the Bounty Hunters' Captain and Bounty Hunter","r":"won","at":"The King's Road","h":["h8"],"tag":"bounty","k":"fight","id":"f16","d":7,"s":1,"sd":7,"imp":2,"score":20,"x":"Spencer makes short work of the Bounty Hunters' Captain and Bounty Hunter on the road to Ironhaven, sent for the price on Spencer's head. Loot: 5 stolen goods, 2 rations."},{"t":"The Azure Stallions vs 2 Bandits and 2 Bandit Captains","r":"won","at":"The King's Road","h":["h3","h12","h14","h18"],"tag":"wild","k":"fight","id":"f17","d":7,"s":1,"sd":7,"imp":2,"score":20,"x":"The Azure Stallions make short work of 2 Bandits and 2 Bandit Captains on the King's Road. Loot: 10 stolen goods, 6 bandit sausages, 4 rations."},{"t":"Cards for Spencer, read by Magister Quillon","at":"the Academy library","h":["h8"],"x":"At the Academy library, Magister Quillon turns Spencer's three cards one at a time: the Two of Wands, the Moon and the World. Some good, some not.","k":"reading","id":"r6","d":7,"s":1,"sd":7,"imp":2,"score":20},{"t":"Cards for Garrett, read by Aunt Crumb","at":"the back of the pie shop","h":["h4"],"x":"Aunt Crumb lays three cards out for Garrett at the back of the pie shop: the Eight of Cups, the Seven of Cups upside down and the Five of Swords. Some good, some not.","k":"reading","id":"r7","d":7,"s":1,"sd":7,"imp":2,"score":20},{"t":"\"The Heron King\" by the fire","at":"camp in Goblin Camp","h":["h11","h6"],"x":"Natasha sings \"The Heron King\" with great conviction. The pitch has gone somewhere else for the night. Echo is very kind about it.","tag":"song","k":"night","id":"n1","d":7,"s":1,"sd":7,"imp":1,"score":10},{"t":"Cards for Chloe, read by Sabine Venn","at":"the toll-house parlour","h":["h17"],"x":"Sabine Venn reads for Chloe at the toll-house parlour and takes a long look at each card: the World, the Fool and Strength. The cards are kind.","k":"reading","id":"r8","d":7,"s":1,"sd":7,"imp":1,"score":10},{"t":"The Azure Stallions vs a Bandit Archer, a Bandit and a Bandit Captain","r":"won","at":"The King's Road","h":["h3","h12","h14","h18"],"tag":"camp","k":"fight","id":"f11","d":6,"s":1,"sd":6,"imp":3,"score":30,"x":"First blood for Varun, Matt McF, Ankit and Mark: The Azure Stallions dispatch a Bandit Archer, a Bandit and a Bandit Captain at their camp on the King's Road, in the dead of night. Varun kept a cool…"},{"t":"The Royal Vigil vs 2 Wolves","r":"won","at":"The Wolf Den","h":["h10","h16"],"tag":"camp","k":"fight","id":"f13","d":6,"s":1,"sd":6,"imp":3,"score":30,"x":"Wolves at the Wolf Den, in the middle of the night: The Royal Vigil sees off 2 of them at their camp. Yomna did more than her share and started none of the trouble. Loot: 2 pelts, 2 fangs & claws, 2…"},{"t":"Cards for Ryan, read by Magister Quillon","at":"a study at the Academy","h":["h15"],"x":"Magister Quillon reads for Ryan at a study at the Academy and takes a long look at each card: the Seven of Cups, the Page of Swords and the King of Swords upside down. Magister Quillon suggests a…","k":"reading","id":"r1","d":6,"s":1,"sd":6,"imp":3,"score":30},{"t":"Cards for Kev, read by Widow Cinder","at":"a cottage at the pithead","h":["h2"],"x":"Widow Cinder reads for Kev at a cottage at the pithead and takes a long look at each card: the Five of Cups, the Eight of Wands upside down and the Fool upside down. Not a spread anyone wants.","k":"reading","id":"r2","d":6,"s":1,"sd":6,"imp":3,"score":30},{"t":"Forge-Bellows Pepper Pot","at":"the Ironhaven feast-day tables","h":["h3"],"x":"Varun eats a Forge-Bellows Pepper Pot at the Ironhaven feast-day tables, elbow to elbow with the whole town. It has a ladle that has never been to the bottom. (8 copper)","tag":"tavern","k":"meal","id":"m1","d":6,"s":1,"sd":6,"imp":2,"score":20},{"t":"Grey Bread with Dripping","h":["h2"],"x":"Mother Grall has written Grey Bread with Dripping on the board at The Pickaxe & Pint in letters a foot high: dish of the week. Kev orders it before sitting down. It is heavy enough to stop a door…","tag":"tavern","k":"meal","id":"m3","d":6,"s":1,"sd":6,"imp":2,"score":20},{"t":"Cards for Robert, read by Aunt Crumb","at":"the back of the pie shop","h":["h7"],"x":"Robert crosses Aunt Crumb's palm with copper at the back of the pie shop, and three cards come up: the King of Cups, the Nine of Wands upside down and the Star. Aunt Crumb taps the middle card and…","k":"reading","id":"r4","d":6,"s":1,"sd":6,"imp":2,"score":20},{"t":"Forge-Bellows Pepper Pot","at":"the Ironhaven feast-day tables","h":["h15"],"x":"Ryan eats a Forge-Bellows Pepper Pot at the Ironhaven feast-day tables, elbow to elbow with the whole town. It is hot enough to make the smiths at the next table respectful. (8 copper)","tag":"tavern","k":"meal","id":"m2","d":6,"s":1,"sd":6,"imp":1,"score":10},{"t":"Rampart Hotpot","h":["h17"],"x":"Chloe points at some Rampart Hotpot on the board at The Sagging Beam without reading the rest. It fights back a little at the edges, where the crust went to war. (1 silver 6 copper)","tag":"tavern","k":"meal","id":"m4","d":6,"s":1,"sd":6,"imp":1,"score":10},{"t":"Fish on Sticks","at":"by the road to Ironhaven","h":["h8"],"x":"Spencer eats Fish on Sticks by the road to Ironhaven by his own fire. They taste of the river and the smoke.","tag":"camp","k":"meal","id":"m5","d":6,"s":1,"sd":6,"imp":1,"score":10},{"t":"Cards for Claire, read by Aunt Crumb","at":"the back of the pie shop","h":["h9"],"x":"Claire sits down across from Aunt Crumb at the back of the pie shop. Three cards: the Page of Swords, the Three of Cups and the Page of Pentacles. The cards are kind.","k":"reading","id":"r3","d":6,"s":1,"sd":6,"imp":1,"score":10},{"t":"Cards for Griffin, read by Aunt Crumb","at":"the back of the pie shop","h":["h5"],"x":"Aunt Crumb lays three cards out for Griffin at the back of the pie shop: the Ten of Wands, the Star upside down and the Hermit. Aunt Crumb goes quiet over the cards.","k":"reading","id":"r5","d":6,"s":1,"sd":6,"imp":1,"score":10},{"t":"The Verdant Sigil vs 4 Goblins and a Giant Rat","r":"won","at":"Goblin Camp","h":["h6","h11","h19"],"tag":"dungeon","k":"fight","id":"f10","d":5,"s":1,"sd":5,"imp":3,"score":30,"x":"First blood for Echo, Natasha and Christian: The Verdant Sigil makes short work of 4 Goblins and a Giant Rat on floor 1 of Goblin Camp. Loot: 6 goblin ears."},{"t":"Sam vs a Wolf","r":"won","at":"The King's Road","h":["h1"],"tag":"road","k":"fight","id":"f4","d":3,"s":1,"sd":3,"imp":3,"score":30,"x":"First blood for Sam: on the road to Ironhaven, Sam dispatches a Wolf. Loot: 1 pelt."},{"t":"Spencer vs a Wolf","r":"won","at":"Whitepeak Pass","h":["h8"],"tag":"wild","k":"fight","id":"f5","d":3,"s":1,"sd":3,"imp":3,"score":30,"x":"First blood for Spencer, who defeats a Wolf just outside Frosthold."},{"t":"Copper Whiskers vs 3 Bandits","r":"won","at":"The King's Road","h":["h13","h9","h7","h5"],"tag":"camp","k":"fight","id":"f6","d":3,"s":1,"sd":3,"imp":3,"score":30,"x":"First blood for Veronika, Claire, Robert and Griffin: in the middle of the night, Copper Whiskers make short work of 3 Bandits at their camp on the road to Ironhaven. Veronika called out every flank…"},{"t":"The Cobalt Storm vs 2 Wolves","r":"won","at":"The Greenwood","h":["h17","h4"],"tag":"road","k":"fight","id":"f7","d":3,"s":1,"sd":3,"imp":3,"score":30,"x":"First blood for Chloe: The Cobalt Storm routs 2 Wolves on the road to the Greenwood, with Chloe everywhere at once. Garrett was thinking about the Ashveil Crypts the whole fight, and the map in his…"},{"t":"Yomna vs a Wolf","r":"won","at":"The King's Road","h":["h10"],"k":"fight","id":"f1","d":1,"s":1,"sd":1,"imp":3,"score":30,"x":"First blood for Yomna: Yomna handles a Wolf on the cart road to the quarry."},{"t":"Mikolaj vs a Wolf","r":"won","at":"The King's Road","h":["h16"],"k":"fight","id":"f2","d":1,"s":1,"sd":1,"imp":3,"score":30,"x":"First blood for Mikolaj: Mikolaj defeats a Wolf on the cart road to the charcoal-burners' camp. Loot: 1 pelt."},{"t":"Garrett vs a Wolf","r":"won","at":"The Greenwood","h":["h4"],"k":"fight","id":"f3","d":1,"s":1,"sd":1,"imp":3,"score":30,"x":"First blood for Garrett: Garrett handles a Wolf on the cart road to the market crossroads. Loot: 1 pelt."}]};